pred_cypher:
MATCH (r:River)-[:flowsThrough]->(c:Country {name: "MM"})
WHERE EXISTS { MATCH (t:River {name: "Mun River"})-[:flowsInto]->(r) }
RETURN r.name, r.length_km

MATCH (c:Country)-[:locatedIn]->(:Continent)
WHERE EXISTS { MATCH (:River {name: "Tobol"})-[:flowsThrough]->(c) }
  AND EXISTS { MATCH (:River {name: "Yemnaya"})-[:flowsThrough]->(c) }
RETURN c.name, c.area_km2

MATCH (r:River)-[:flowsInto]->(o:Ocean {name: "Atlantic Ocean"})
WHERE EXISTS { MATCH (r)-[:flowsThrough]->(:Country {name: "CGO"}) }
RETURN DISTINCT r.name

MATCH (r:River)-[:partOf]->(db:DrainageBasin {name: "Congo basin"})
WHERE EXISTS { MATCH (r)-[:flowsInto]->(:Ocean {name: "Atlantic Ocean"}) }
RETURN r.name, r.discharge_m3_s
